window.__texto({"id": "732439622", "paragrafos": [{"c": "identifica", "t": "PORTARIA SDA/MAPA Nº 1.684, DE 16 DE SETEMBRO DE 2026 (*)"}, {"c": "ementa", "t": "Submete à Consulta Pública a proposta de portaria voltada a estabelecer os procedimentos de habilitação de estabelecimentos nacionais para exportação e de trânsito e certificação sanitária aplicáveis aos produtos de origem animal."}, {"c": "dou-paragraph", "t": "O SECRETÁRIO DE DEFESA AGROPECUÁRIA, DO MINISTÉRIO DA AGRICULTURA E PECUÁRIA, no uso das atribuições que lhe conferem o arts. 23 e 48 do Anexo I do Decreto nº 12.642, de 1º de outubro de 2025, tendo em vista o disposto na Lei nº 1.283, de 18 de dezembro de 1950, na Lei nº 7.889, de 23 de novembro de 1989, no Decreto nº 9.013, de 29 de março de 2017, e o que consta do Processo 21000.075473/2025-05, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica submetida à consulta pública, pelo prazo de 75 dias (setenta e cinco), o anexo desta portaria, contendo a proposta de portaria voltada a estabelecer os procedimentos de habilitação de estabelecimentos nacionais para exportação e de trânsito e certificação sanitária aplicáveis aos produtos de origem animal."}, {"c": "dou-paragraph", "t": "Parágrafo único. O projeto de portaria encontra-se disponível na página eletrônica do Ministério da Agricultura e Pecuária, https://www.gov.br/agricultura/pt-br, na seção de consultas públicas."}, {"c": "dou-paragraph", "t": "Art. 2º As sugestões tecnicamente fundamentadas deverão ser encaminhadas por meio do Sistema de Monitoramento de Atos Normativos - SISMAN, da Secretaria de Defesa Agropecuária, por acesso eletrônico: http://sistemasweb.agricultura.gov.br/pages/SISMAN.html."}, {"c": "dou-paragraph", "t": "Parágrafo único. Para acesso ao Sistema de Monitoramento de Atos Normativos - SISMAN, o usuário deverá efetuar cadastro prévio no Sistema de Solicitação de Acesso - SOLICITA, pelo portal eletrônico: https://sistemasweb.agricultura.gov.br/solicita/."}, {"c": "dou-paragraph", "t": "Art. 3º Findo o prazo estabelecido no caput do art. 1º desta Portaria, o Departamento de Inspeção de Produtos de Origem Animal avaliará as sugestões recebidas e procederá às adequações pertinentes para posterior publicação da portaria no Diário Oficial da União."}, {"c": "dou-paragraph", "t": "Art. 4º Esta portaria entra em vigor na data de sua publicação."}, {"c": "assina", "t": "CARLOS GOULART"}, {"c": "dou-paragraph", "t": "ANEXO"}, {"c": "dou-paragraph", "t": "Estabelece os procedimentos de habilitação de estabelecimentos nacionais para exportação e de trânsito e certificação sanitária aplicáveis aos produtos de origem animal."}, {"c": "dou-paragraph", "t": "O SECRETÁRIO DE DEFESA AGROPECUÁRIA, DO MINISTÉRIO DA AGRICULTURA E PECUÁRIA, no uso das atribuições que lhe conferem o art. 23 e o art. 48 do Anexo I ao Decreto nº 12.642, de 1º de outubro de 2025, e tendo em vista o disposto na Lei nº 1.283, de 18 de dezembro de 1950, na Lei nº 7.889, de 23 de novembro de 1989, no Decreto nº 9.013, de 29 de março de 2017, e o que consta do Processo nº 21000.075473/2025-05,"}, {"c": "dou-paragraph", "t": "resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Ficam estabelecidos os procedimentos de habilitação de estabelecimentos nacionais para exportação e de trânsito e certificação sanitária aplicáveis aos produtos de origem animal provenientes de estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal da Secretaria de Defesa Agropecuária do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "CAPÍTULO I"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES PRELIMINARES"}, {"c": "dou-paragraph", "t": "Art. 2º São adotados os seguintes conceitos para fins desta portaria:"}, {"c": "dou-paragraph", "t": "I - Habilitação é a concessão de autorização ao estabelecimento nacional, registrado junto ao Departamento de Inspeção de Produtos de Origem Animal, para exportação de produtos de origem animal a um determinado país ou mercado comum;"}, {"c": "dou-paragraph", "t": "II - Lista de habilitação é o rol por meio do qual se divulgam os estabelecimentos nacionais, registrados no Departamento de Inspeção de Produtos de Origem Animal, habilitados e autorizados a exportar produtos de origem animal;"}, {"c": "dou-paragraph", "t": "III - País importador é o país de destino dos produtos de origem animal exportados pelos estabelecimentos nacionais, registrados no Departamento de Inspeção de Produtos de Origem Animal;"}, {"c": "dou-paragraph", "t": "IV - País ou mercado comum importador que não exige habilitação específica é aquele para o qual a autorização de exportação se dá mediante o registro do estabelecimento nacional no Departamento de Inspeção de Produtos de Origem Animal, sendo que o registro em sistema informatizado do Ministério da Agricultura e Pecuária deve ser por meio de habilitação para o país \"Brasil\";"}, {"c": "dou-paragraph", "t": "V - País ou mercado comum importador que exige habilitação é aquele para o qual a autorização de exportação se dá mediante inclusão do estabelecimento em lista de habilitação, sendo que o registro em sistema informatizado do Ministério da Agricultura e Pecuária deve ser por meio de habilitação para o país ou mercado comum;"}, {"c": "dou-paragraph", "t": "VI - Requisitos sanitários são declarações técnicas contidas em certificados acordados, apenas quando essenciais e alinhadas às diretrizes internacionalmente reconhecidas, acordadas entre autoridades sanitárias do país exportador e do país importador, para assegurar os requisitos de segurança dos produtos, a proteção à saúde pública e à saúde animal;"}, {"c": "dou-paragraph", "t": "VII - Trânsito nacional é a movimentação de produtos dentro do Brasil, seja entre estabelecimentos ou do estabelecimento até o ponto de egresso do território nacional;"}, {"c": "dou-paragraph", "t": "VIII - Trânsito internacional é a movimentação do produto desde o ponto de egresso do território nacional até o ponto de controle da autoridade sanitária do país importador;"}, {"c": "dou-paragraph", "t": "IX - Redirecionamento de produto é a alteração do destinatário ou do destino originalmente previsto para sua exportação, podendo ser enviado a outro país importador ou ao mercado interno;"}, {"c": "dou-paragraph", "t": "X - Unidade emitente é o Serviço de Inspeção Federal, a Central de Certificação ou a Unidade de Vigilância Agropecuária Internacional responsável por emitir os documentos de trânsito, bem como os estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal que emitem Declarações de Produtos de Origem Animal;"}, {"c": "dou-paragraph", "t": "XI - Certificação sanitária é o procedimento pelo qual a autoridade do Ministério da Agricultura e Pecuária atesta, por meio de documento em papel, digital ou eletrônico, que os produtos cumprem os requisitos sanitários, técnicos e legais;"}, {"c": "dou-paragraph", "t": "XII - Guia de Trânsito é o documento oficial, em papel ou digital, emitido pela autoridade do Ministério da Agricultura e Pecuária para o trânsito nacional de produtos, conforme requisitos sanitários, técnicos e legais estabelecidos nesta portaria e nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária;"}, {"c": "dou-paragraph", "t": "XIII - Certificado Sanitário é o documento oficial, em papel, digital ou eletrônico, que descreve e atesta os atributos dos produtos destinados ao trânsito nacional ou internacional;"}, {"c": "dou-paragraph", "t": "XIV - Certificado Sanitário Nacional é o documento oficial emitido pela autoridade do Ministério da Agricultura e Pecuária, que respalda o trânsito nacional de produtos;"}, {"c": "dou-paragraph", "t": "XV - Certificado Sanitário Internacional é o documento oficial emitido pela autoridade do Ministério da Agricultura e Pecuária, que respalda o trânsito internacional de produtos;"}, {"c": "dou-paragraph", "t": "XVI - A Carta de Correção é um documento oficial, em papel ou digital, usado para corrigir dados de preenchimento do Certificado Sanitário Internacional válido;"}, {"c": "dou-paragraph", "t": "XVII - Declaração de Produtos de Origem Animal é o documento, em papel ou digital, emitido por representante do estabelecimento para comprovar que os produtos a serem certificados atendem aos requisitos sanitários, técnicos e legais para o trânsito nacional de produtos e para solicitar demais documentos de trânsito;"}, {"c": "dou-paragraph", "t": "XVIII - Medida de contingência é o procedimento em que a emissão do Certificado Sanitário Nacional, do Certificado Sanitário Internacional, da Carta de Correção, da Guia de Trânsito e da Declaração de Produtos de Origem Animal é feita manualmente, fora do sistema informatizado do Ministério da Agricultura e Pecuária, quando este estiver temporariamente indisponível;"}, {"c": "dou-paragraph", "t": "XIX - Comércio institucional é a modalidade de comércio na qual o produto fabricado para exportação é direcionado ao mercado interno, sem ser colocado à venda direta ao consumidor final na forma em que se apresenta, sendo realizada entre:"}, {"c": "dou-paragraph", "t": "a) empresas registradas no Departamento de Inspeção de Produtos de Origem Animal;"}, {"c": "dou-paragraph", "t": "b) empresas registradas no Departamento de Inspeção de Produtos de Origem Animal e empresas registradas em outros órgãos fiscalizadores; ou"}, {"c": "dou-paragraph", "t": "c) empresas registradas no Departamento de Inspeção de Produtos de Origem Animal e instituições como, por exemplo, hospitais, creches e restaurantes."}, {"c": "dou-paragraph", "t": "XX - Amostra sem valor comercial é a quantidade, fragmento ou parte de um produto usada apenas para mostrar suas características, como natureza, tipo e qualidade;"}, {"c": "dou-paragraph", "t": "XXI - Revisão de autocontrole é a conferência documental e física da carga e do produto pelo estabelecimento, incluindo a coleta de amostras se aplicável; e"}, {"c": "dou-paragraph", "t": "XXII - Reinspeção oficial é a conferência documental e física da carga e do produto pelo serviço oficial, incluindo a coleta de amostras se aplicável."}, {"c": "dou-paragraph", "t": "CAPÍTULO II"}, {"c": "dou-paragraph", "t": "HABILITAÇÃO"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Modalidades de habilitação"}, {"c": "dou-paragraph", "t": "Art. 3º A habilitação pode ocorrer nas seguintes modalidades:"}, {"c": "dou-paragraph", "t": "I - pré-listagem pelo Departamento de Inspeção de Produtos de Origem Animal, com comunicação ao país ou mercado comum importador;"}, {"c": "dou-paragraph", "t": "II - indicação pelo Ministério da Agricultura e Pecuária;"}, {"c": "dou-paragraph", "t": "III - indicação pelas autoridades sanitárias do país ou mercado comum importador;"}, {"c": "dou-paragraph", "t": "IV - missão de auditoria pelas autoridades sanitárias do país ou mercado comum importador; ou"}, {"c": "dou-paragraph", "t": "V - monografia de processo."}, {"c": "dou-paragraph", "t": "Parágrafo único. O Departamento de Inspeção de Produtos de Origem Animal ou o país ou mercado comum importador podem estabelecer outras modalidades de habilitação."}, {"c": "dou-paragraph", "t": "Art. 4º A modalidade de habilitação por pré-listagem consiste na habilitação prévia do estabelecimento nacional pelo Departamento de Inspeção de Produtos de Origem Animal em sistema informatizado do Ministério da Agricultura e Pecuária, com posterior comunicação ao país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "§ 1º O Departamento de Inspeção de Produtos de Origem Animal informa ao país ou mercado comum importador o reconhecimento brasileiro de que o estabelecimento nacional está autorizado a exportar."}, {"c": "dou-paragraph", "t": "§ 2º O estabelecimento nacional deve acompanhar o registro da sua habilitação no sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 3º Caso o país ou mercado comum importador registre uma data de habilitação diferente da comunicada pelo Departamento de Inspeção de Produtos de Origem Animal, tal informação será atualizada em sistema informatizado do Ministério da Agricultura e Pecuária, cabendo ao estabelecimento nacional ajustar o início da data de produção para aquele destino."}, {"c": "dou-paragraph", "t": "Art. 5º A modalidade de habilitação por indicação pelo Ministério da Agricultura e Pecuária consiste na indicação do estabelecimento às autoridades sanitárias do país ou mercado comum importador, informando que o estabelecimento cumpre seus requisitos sanitários."}, {"c": "dou-paragraph", "t": "Parágrafo único. O Departamento de Inspeção de Produtos de Origem Animal comunica ao estabelecimento quando a sua aprovação for concedida pelas autoridades sanitárias do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "Art. 6º A modalidade de habilitação por indicação das autoridades sanitárias do país ou mercado comum importador consiste no reconhecimento de que o estabelecimento nacional está autorizado a exportar."}, {"c": "dou-paragraph", "t": "§ 1º O Departamento de Inspeção de Produtos de Origem Animal comunica o estabelecimento quando a sua aprovação for concedida pelas autoridades sanitárias do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "§ 2º A indicação de habilitação de que trata o caput pode ocorrer das seguintes formas:"}, {"c": "dou-paragraph", "t": "I - comunicação das autoridades sanitárias do país ou mercado comum importador ao ministério da Agricultura e Pecuária; ou"}, {"c": "dou-paragraph", "t": "II - comunicação do estabelecimento ao serviço oficial com apresentação de documento fornecido pelas autoridades sanitárias competentes do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "Art. 7º A modalidade de habilitação por missão de auditoria consiste na avaliação in loco ou remota do estabelecimento pela autoridade sanitária do país ou mercado comum importador quanto ao cumprimento de requisitos sanitários e demais exigências para exportação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O Departamento de Inspeção de Produtos de Origem Animal deve divulgar a lista de estabelecimentos aprovados pelas autoridades sanitárias do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "Art. 8º A modalidade de habilitação por monografia de processo consiste em uma avaliação documental do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "§ 1º Os trâmites da habilitação por monografia de processo são tratados diretamente entre o estabelecimento nacional e o país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "§ 2º A monografia de processo pode ser assinada pelo serviço oficial e enviada pelo Ministério da Agricultura e Pecuária, mediante comprovação de solicitação formal das autoridades sanitárias do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Solicitação de habilitação"}, {"c": "dou-paragraph", "t": "Art. 9º O estabelecimento deve demonstrar a sua capacidade de cumprir:"}, {"c": "dou-paragraph", "t": "I - os requisitos sanitários do país ou mercado comum importador; e"}, {"c": "dou-paragraph", "t": "II - o acordo ou protocolo bilateral, se houver."}, {"c": "dou-paragraph", "t": "§ 1º O Departamento de Inspeção de Produtos de Origem Animal pode determinar a realização de auditorias para apoiar a sua avaliação."}, {"c": "dou-paragraph", "t": "§ 2º Nos casos em que não exista acordo ou protocolo bilateral firmado entre o Brasil e o país ou mercado comum importador para o produto, o estabelecimento nacional deve verificar se a autoridade sanitária autoriza a sua importação sem a exigência de habilitação prévia, cumprida a legislação nacional."}, {"c": "dou-paragraph", "t": "Art. 10. O estabelecimento deve apresentar os seguintes documentos:"}, {"c": "dou-paragraph", "t": "I - formulário de solicitação de habilitação;"}, {"c": "dou-paragraph", "t": "II - planilha de solicitação de habilitação:"}, {"c": "dou-paragraph", "t": "a) genérica do Departamento de Inspeção de Produtos de Origem Animal; ou"}, {"c": "dou-paragraph", "t": "b) específica do país ou mercado comum importador, quando aplicável."}, {"c": "dou-paragraph", "t": "III - outros documentos exigidos pelo país ou mercado comum importador, quando aplicável."}, {"c": "dou-paragraph", "t": "Art. 11. A solicitação de habilitação deve ser realizada pelo estabelecimento nacional por país ou mercado comum importador, de forma individualizada."}, {"c": "dou-paragraph", "t": "Art. 12. Os documentos exigidos pelo país ou mercado comum importador devem ser preenchidos no idioma português, em vernáculo, e no idioma exigido pelo país importador, sem alterações de forma ou conteúdo."}, {"c": "dou-paragraph", "t": "§ 1º Os documentos citados no caput devem ser acompanhados de declaração de integralidade e fidelidade."}, {"c": "dou-paragraph", "t": "§ 2º Os documentos do Ministério da Agricultura e Pecuária são emitidos somente no idioma português, em vernáculo, e devem ter tradução livre, providenciada pelo estabelecimento nacional, quando exigido pelo país importador."}, {"c": "dou-paragraph", "t": "Art. 13. Documentos apresentados em idioma estrangeiro devem seguir as exigências de idioma do país importador."}, {"c": "dou-paragraph", "t": "Art. 14. Documentos ilegíveis, incorretos ou incompletos devem ser indeferidos e devolvidos ao estabelecimento nacional para correções."}, {"c": "dou-paragraph", "t": "Art. 15. A critério das autoridades sanitárias do país ou mercado comum importador, pode ser exigido:"}, {"c": "dou-paragraph", "t": "I - adesão a protocolos privados;"}, {"c": "dou-paragraph", "t": "II - comprovação de certificações específicas;"}, {"c": "dou-paragraph", "t": "III - pagamento de taxas;"}, {"c": "dou-paragraph", "t": "IV - cadastro em sistema informatizado;"}, {"c": "dou-paragraph", "t": "V - definição de prazo de validade;"}, {"c": "dou-paragraph", "t": "VI - procedimentos de renovação; e"}, {"c": "dou-paragraph", "t": "VII - outros requisitos para a habilitação."}, {"c": "dou-paragraph", "t": "Art. 16. É responsabilidade do estabelecimento nacional acompanhar o trâmite do seu processo de habilitação, bem como do registro e da atualização da sua habilitação no sistema informatizado do Ministério da Agricultura e Pecuária e no do país ou mercado comum importador, quando aplicável."}, {"c": "dou-paragraph", "t": "Parágrafo único. O Ministério da Agricultura e Pecuária não prevê prazos para a conclusão do processo de habilitação, pois depende da análise pelas autoridades sanitárias do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "Art. 17. É de responsabilidade do estabelecimento exportador a verificação, junto às autoridades sanitárias do país ou mercado comum importador, se não existem pendências relativas à sua habilitação."}, {"c": "dou-paragraph", "t": "Parágrafo único. A verificação citada no caput deve ser realizada antes do início da exportação."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Manutenção da habilitação"}, {"c": "dou-paragraph", "t": "Art. 18. Obtida a habilitação, o estabelecimento nacional deve atualizar os seus programas de autocontrole para contemplar os requisitos sanitários estabelecidos pela autoridade sanitária do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "Art. 19. A extensão do escopo de habilitação consiste na inclusão de produto padronizado ou categoria de produto."}, {"c": "dou-paragraph", "t": "§ 1º A extensão do escopo de habilitação deve ser comunicada ao país ou mercado comum importador para o qual o estabelecimento nacional se encontra habilitado, antes do início da exportação."}, {"c": "dou-paragraph", "t": "§ 2º A comunicação da extensão do escopo de habilitação pode ser dispensada a critério do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "§ 3º Os procedimentos de extensão do escopo de habilitação do estabelecimento constam nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 20. A renovação de habilitação, quando exigida pelo país ou mercado comum importador, deve ser solicitada com antecedência, observados os prazos estabelecidos."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os procedimentos de renovação de habilitação do estabelecimento constam nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 21. A alteração cadastral deve ser comunicada pelo estabelecimento nacional aos respectivos países ou mercados comuns importadores para os quais possui habilitação."}, {"c": "dou-paragraph", "t": "§ 1º Os procedimentos de alteração cadastral do estabelecimento constam nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º O país ou mercado comum importador pode exigir novos documentos ou nova solicitação de habilitação."}, {"c": "dou-paragraph", "t": "§ 3º A critério do Departamento de Inspeção de Produtos de Origem Animal, podem ser emitidos documentos de trânsito com os dados cadastrais anteriores, desde que a alteração cadastral já tenha sido comunicada ao país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "§ 4º Quando necessário, o estabelecimento nacional pode requerer prazo junto à autoridade sanitária do país ou mercado comum importador, para uso de estoques de rotulagem com dados antigos e verificar pendências de habilitação antes da exportação."}, {"c": "dou-paragraph", "t": "§ 5º O estabelecimento nacional deve solicitar prazo para a utilização do estoque de rotulagem com dados cadastrais anteriores à sua atualização junto à autoridade sanitária do país ou mercado comum importador, se necessário."}, {"c": "dou-paragraph", "t": "§ 6º O estabelecimento deve verificar junto à autoridade sanitária do país ou mercado comum importador se não existem pendências quanto à sua habilitação, previamente ao envio de seus produtos."}, {"c": "dou-paragraph", "t": "CAPÍTULO III"}, {"c": "dou-paragraph", "t": "TRÂNSITO E CERTIFICAÇÃO"}, {"c": "dou-paragraph", "t": "Art. 22. Os documentos de trânsito incluem:"}, {"c": "dou-paragraph", "t": "I - Certificados Sanitários Nacionais;"}, {"c": "dou-paragraph", "t": "II - Certificados Sanitários Internacionais;"}, {"c": "dou-paragraph", "t": "III - Guias de Trânsito;"}, {"c": "dou-paragraph", "t": "IV - Declaração de Produtos de Origem Animal;"}, {"c": "dou-paragraph", "t": "V - Declarações Adicionais;"}, {"c": "dou-paragraph", "t": "VI - Cartas de Correção; e"}, {"c": "dou-paragraph", "t": "VII - outros a critério do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 23. Os produtos produzidos em estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal devem ser destinados ao mercado interno, nacional, ou ao mercado externo, internacional."}, {"c": "dou-paragraph", "t": "§ 1º O trânsito dos produtos destinados ao mercado externo deve ocorrer de estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal para:"}, {"c": "dou-paragraph", "t": "I - descarregamento, processamento ou armazenagem em outro estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal;"}, {"c": "dou-paragraph", "t": "II - portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação com Unidade de Vigilância Agropecuária Internacional, para procedimentos de desembaraço para exportação;"}, {"c": "dou-paragraph", "t": "III - estabelecimentos registrados ou cadastrados em outros órgãos de fiscalização; ou"}, {"c": "dou-paragraph", "t": "IV - outros estabelecimentos registrados ou cadastrados no Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º A garantia das condições adequadas de conservação, localização, rastreabilidade, identificação e inviolabilidade do produto é de responsabilidade de quem tem a sua propriedade."}, {"c": "dou-paragraph", "t": "§ 3º O Departamento de Inspeção de Produtos de Origem Animal pode autorizar outros fluxos de trânsito diferentes do disposto neste artigo por particularidades de processos produtivos, visando a rastreabilidade e as condições para a certificação sanitária."}, {"c": "dou-paragraph", "t": "Art. 24. Para o trânsito de produtos em embalagens ou contentores que impossibilitem a aposição de rótulos, a rotulagem deve ser anexada aos documentos de trânsito."}, {"c": "dou-paragraph", "t": "Art. 25. O estabelecimento nacional deve descrever em seus programas de autocontrole os procedimentos de solicitação dos documentos de trânsito, bem como de seu preenchimento, e as ações que devem ser adotadas no caso de desvios."}, {"c": "dou-paragraph", "t": "Art. 26. O Departamento de Inspeção de Produtos de Origem Animal pode comunicar à autoridade sanitária do país importador sobre não conformidades na certificação sanitária."}, {"c": "dou-paragraph", "t": "Art. 27. Os modelos de carimbos são estabelecidos nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária e não podem ser alterados em sua forma ou seu conteúdo."}, {"c": "dou-paragraph", "t": "Art. 28. O estabelecimento nacional deve conferir o produto recebido com os seus documentos de trânsito, bem como conferir a autenticidade dos documentos com consulta do código de autenticidade no sítio eletrônico do Ministério da Agricultura e Pecuária ou com leitura do seu QR code."}, {"c": "dou-paragraph", "t": "§ 1º Caso o estabelecimento nacional de destino verifique divergências entre o produto recebido e os seus documentos de trânsito, o produto deve ser segregado e o estabelecimento de origem comunicado."}, {"c": "dou-paragraph", "t": "§ 2º O estabelecimento nacional de origem e o estabelecimento nacional de destino dos produtos devem manter registros das comunicações de divergências, assim como medidas corretivas e preventivas descritas em seus programas de autocontrole."}, {"c": "dou-paragraph", "t": "§ 3º Os produtos recebidos que não tenham respaldo no documento de trânsito devem ser segregados pelo estabelecimento nacional de destino e desabilitados para exportação, atendido o redirecionamento disposto nesta portaria."}, {"c": "dou-paragraph", "t": "§ 4º O serviço oficial deve ser comunicado nos casos em que não seja comprovada a autenticidade dos documentos de trânsito."}, {"c": "dou-paragraph", "t": "§ 5º É proibido o uso dos documentos de trânsito de que tratam os §§ 1º e 3º como documentos de respaldo para a emissão de novos documentos de trânsito."}, {"c": "dou-paragraph", "t": "§ 6º O estabelecimento de destino deve responder solidariamente ao estabelecimento que solicitou a emissão do Certificado Sanitário ou da Guia de Trânsito, ou que emitiu a Declaração de Produtos de Origem Animal, quando não cumprir o estabelecido neste artigo."}, {"c": "dou-paragraph", "t": "Art. 29. É proibido o recebimento de produtos:"}, {"c": "dou-paragraph", "t": "I - acompanhados de documento de trânsito destinado a outro estabelecimento nacional;"}, {"c": "dou-paragraph", "t": "II - no caso de identificação de divergência na numeração do lacre; ou"}, {"c": "dou-paragraph", "t": "III - no caso de extravio do lacre descrito no documento de trânsito, sem a devida justificativa e comprovação."}, {"c": "dou-paragraph", "t": "Parágrafo único. Nos casos de que tratam os incisos II e III, a carga deve ser submetida à reinspeção oficial."}, {"c": "dou-paragraph", "t": "Art. 30. Para a rastreabilidade de composição da carga:"}, {"c": "dou-paragraph", "t": "I - os produtos que sejam carregados em diferentes estabelecimentos, registrados no Departamento de Inspeção de Produtos de Origem Animal, em um mesmo contentor de carga de exportação, devem solicitar, a cada parcela carregada, a emissão de um novo Certificado Sanitário Nacional ou emitir uma nova Declaração de Produtos de Origem Animal, tendo como base o documento anteriormente emitido até a formação completa da carga; e"}, {"c": "dou-paragraph", "t": "II - os produtos em um mesmo contentor de carga que sejam descarregados em diferentes estabelecimentos, registrados no Departamento de Inspeção de Produtos de Origem Animal, devem solicitar, a cada parcela descarregada, a emissão de novo Certificado Sanitário Nacional ou emitir nova Declaração de Produtos de Origem Animal, tendo como respaldo o documento anteriormente emitido até o descarregamento completo da carga."}, {"c": "dou-paragraph", "t": "Parágrafo único. Todos os estabelecimentos nacionais envolvidos no carregamento ou no descarregamento podem responder solidariamente por eventuais não conformidades constatadas na carga, conforme avaliação dos registros de seus programas de autocontrole."}, {"c": "dou-paragraph", "t": "Art. 31. Os produtos de que trata esta portaria devem apresentar o seu documento de trânsito para serem recebidos no estabelecimento nacional registrado no Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 1º Os produtos que ainda não apresentem o Certificado Sanitário Nacional emitido, a critério do seu estabelecimento de destino, podem ser descarregados e conferidos com a Declaração de Produtos de Origem Animal, manipulados e segregados."}, {"c": "dou-paragraph", "t": "§ 2º Os produtos de que trata o § 1º poderão ser expedidos somente quando o Certificado Sanitário Nacional seja apresentado e conferido com a carga."}, {"c": "dou-paragraph", "t": "§ 3º Ao manipular e segregar os produtos antes do recebimento do Certificado Sanitário Nacional, o estabelecimento nacional assume os riscos em realizar o seu processamento e deve garantir a sua rastreabilidade."}, {"c": "dou-paragraph", "t": "§ 4º Não se aplica o § 1º para os produtos destinados pelo serviço oficial ao aproveitamento condicional, nem para os produtos destinados pelo estabelecimento nacional à destinação industrial."}, {"c": "dou-paragraph", "t": "Art. 32. O Departamento de Inspeção de Produtos de Origem Animal deve auditar:"}, {"c": "dou-paragraph", "t": "I - os procedimentos de solicitação de emissão do Certificado Sanitário ou da Guia de Trânsito e de emissão da Declaração de Produtos de Origem Animal pelo estabelecimento nacional; e"}, {"c": "dou-paragraph", "t": "II - os procedimentos de emissão dos documentos de trânsito pelas suas unidades emitentes."}, {"c": "dou-paragraph", "t": "§ 1º Os procedimentos de auditoria devem estar estabelecidos nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º As unidades da Vigilância Agropecuária Internacional emitentes também estão sujeitas à auditoria, realizada em articulação com o Departamento de Serviços Técnicos, da Secretaria de Defesa Agropecuária, do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Declaração de Produtos de Origem Animal"}, {"c": "dou-paragraph", "t": "Art. 33. A Declaração de Produtos de Origem Animal deve ser emitida pelo Responsável Técnico ou pelos responsáveis do Controle de Qualidade indicados pelo estabelecimento nacional."}, {"c": "dou-paragraph", "t": "§ 1º A Declaração de Produtos de Origem Animal é considerada emitida após a sua assinatura eletrônica, dispensada a sua emissão em papel."}, {"c": "dou-paragraph", "t": "§ 2º Caso haja a solicitação de apresentação da via impressa da Declaração de Produtos de Origem Animal por autoridade fiscalizadora, a mesma deve ser providenciada pelo estabelecimento nacional."}, {"c": "dou-paragraph", "t": "Art. 34. A emissão da Declaração de Produtos de Origem Animal deve ser realizada em sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 1º A Declaração de Produtos de Origem Animal deve atender ao modelo oficial disponível no sistema informatizado, sendo proibida qualquer alteração de forma e conteúdo."}, {"c": "dou-paragraph", "t": "§ 2º No caso de indisponibilidade temporária do sistema informatizado, os documentos de respaldo para a solicitação de documentos de trânsito devem ser apresentados em papel ou outro meio digital."}, {"c": "dou-paragraph", "t": "§ 3º No caso de indisponibilidade temporária do sistema informatizado, a Declaração de Produtos de Origem Animal pode ser emitida em Medida de Contingência, conforme diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 4º A Declaração de Produtos de Origem Animal emitida em medida de contingência deve ser incluída no sistema informatizado imediatamente após o retorno da sua disponibilidade."}, {"c": "dou-paragraph", "t": "Art. 35. A emissão da Declaração de Produtos de Origem Animal é obrigatória nas seguintes situações:"}, {"c": "dou-paragraph", "t": "I - para a solicitação de emissão dos documentos de trânsito pelo estabelecimento nacional à unidade emitente do serviço oficial;"}, {"c": "dou-paragraph", "t": "II - para o trânsito de produtos destinados ao comércio internacional, nos seguintes casos:"}, {"c": "dou-paragraph", "t": "a) entre estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal para país importador que não exige habilitação;"}, {"c": "dou-paragraph", "t": "b) entre estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal, quando tiverem destinação industrial, sendo processados, ou utilizados como matéria-prima de outros produtos para exportação, para país importador que não exige habilitação;"}, {"c": "dou-paragraph", "t": "c) de estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal para estabelecimento registrado ou cadastrado em outro órgão fiscalizador, para país importador que não exige habilitação;"}, {"c": "dou-paragraph", "t": "d) de estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal para portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação para país importador que não exige habilitação, com a certificação sanitária internacional realizada pela Unidade de Vigilância Agropecuária Internacional, seja:"}, {"c": "dou-paragraph", "t": "1. como carga solta ou fracionada, em porão de navio ou de aeronave; ou"}, {"c": "dou-paragraph", "t": "2. quando ocorrer a transferência do produto para o contentor de carga de exportação nestes locais."}, {"c": "dou-paragraph", "t": "e) para o trânsito de portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação para estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal, no caso de transferência de produtos não exportados, quando houver Certificado Sanitário vigente que respalde a carga e o lacre esteja intacto, garantindo a inviolabilidade da carga, para país importador que exige ou não a habilitação."}, {"c": "dou-paragraph", "t": "III - para o trânsito de produtos entre estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal quando tiverem destinação industrial ou condenação pelo estabelecimento;"}, {"c": "dou-paragraph", "t": "IV - para o trânsito de produtos entre estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal e estabelecimentos registrados em outro órgão fiscalizador, quando tiverem destinação industrial, condenação, inutilização ou outros destinos dados pelo estabelecimento, conforme a legislação;"}, {"c": "dou-paragraph", "t": "V - para o trânsito de resíduos animais, dos estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal aos estabelecimentos de processamento, conforme a legislação; e"}, {"c": "dou-paragraph", "t": "VI - para o trânsito de produtos não destinados ao mercado externo, nos casos definidos pelo Departamento de Saúde Animal da Secretaria de Defesa Agropecuária do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. O disposto neste artigo se aplica para o trânsito de produtos que serão processados ou serão utilizados como matéria-prima de outros produtos para exportação, garantida a sua rastreabilidade."}, {"c": "dou-paragraph", "t": "Art. 36. A Declaração de Produtos de Origem Animal deve ser emitida para o país importador que exige a habilitação do estabelecimento nacional processador final, mesmo quando dispensada a habilitação dos estabelecimentos nacionais de abate ou fornecedores de matéria-prima."}, {"c": "dou-paragraph", "t": "Art. 37. A Declaração de Produtos de Origem Animal deve ter respaldo nos programas de autocontrole, em atendimento aos requisitos higiênico-sanitários e tecnológicos estabelecidos na legislação, com vistas a assegurar a segurança, a identidade, a qualidade e a integridade de seus produtos, desde a obtenção e recepção das matérias-primas, dos ingredientes e dos insumos, até a sua expedição e transporte, com registros auditáveis."}, {"c": "dou-paragraph", "t": "Parágrafo único. Ao emitir a Declaração de Produtos de Origem Animal nas situações do art. 35, incisos I e II, o estabelecimento declara que o produto a ser certificado atende aos Requisitos Sanitários do país importador, se houver."}, {"c": "dou-paragraph", "t": "Art. 38. É proibida a emissão de Declaração de Produtos de Origem Animal se o estabelecimento não apresentar os respectivos documentos de respaldo."}, {"c": "dou-paragraph", "t": "Parágrafo único. O estabelecimento deve manter em arquivo os documentos de respaldo da Declaração de Produtos de Origem Animal pelo período de dois anos após expirado o prazo de validade dos produtos, seja em papel ou digital."}, {"c": "dou-paragraph", "t": "Art. 39. O trânsito do produto só pode iniciar após a emissão da Declaração de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 40. É obrigatória a comprovação do recebimento das matérias-primas e dos produtos respaldados por Declaração de Produtos de Origem Animal de destinação industrial, condenação ou inutilização pelo estabelecimento de destino junto ao emitente, por meio de registros auditáveis."}, {"c": "dou-paragraph", "t": "Art. 41. A Declaração de Produtos de Origem Animal está dispensada para a emissão de Certificado Sanitário se a autoridade sanitária do país importador dispensar o Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "Parágrafo único. A dispensa de que trata o caput não dispensa a exigência de Declarações de Produtos de Origem Animal para o trânsito entre estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Guia de trânsito e Certificado Sanitário"}, {"c": "dou-paragraph", "t": "Subseção I"}, {"c": "dou-paragraph", "t": "Requisitos para emissão de Certificado Sanitário e Guia de Trânsito"}, {"c": "dou-paragraph", "t": "Art. 42. O estabelecimento nacional deve apresentar os seguintes documentos de respaldo para solicitar o Certificado Sanitário ou a Guia de Trânsito:"}, {"c": "dou-paragraph", "t": "I - Declaração de Produtos de Origem Animal de solicitação de Certificado Sanitário ou de Guia de Trânsito;"}, {"c": "dou-paragraph", "t": "II - Declaração de Produtos de Origem Animal de respaldo do trânsito entre estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal, quando aplicável;"}, {"c": "dou-paragraph", "t": "III - Declaração de Produtos de Origem Animal de respaldo do trânsito de retorno para estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal, nos casos de que trata o art. 35, inc. II, alínea 'e';"}, {"c": "dou-paragraph", "t": "IV - Certificado Sanitário Nacional de respaldo do trânsito entre estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal, quando aplicável;"}, {"c": "dou-paragraph", "t": "V - Certificado Sanitário Internacional, quando aplicável;"}, {"c": "dou-paragraph", "t": "VI - nota fiscal; e"}, {"c": "dou-paragraph", "t": "VII - outros documentos estabelecidos pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Parágrafo único. A relação de documentos de respaldo de que trata o inciso VII será estabelecida nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 43. A certificação sanitária do produto deve possuir respaldo em todas as fases do seu processo de produção e do seu trânsito, garantindo a segurança, a identidade, a qualidade e a rastreabilidade para o fim a que se destina."}, {"c": "dou-paragraph", "t": "Art. 44. É proibida a emissão do Certificado Sanitário ou da Guia de Trânsito se o estabelecimento não apresentar os respectivos documentos de respaldo."}, {"c": "dou-paragraph", "t": "Art. 45. A emissão do Certificado Sanitário ou da Guia de Trânsito deve ser solicitada à unidade emitente, pelo estabelecimento nacional onde os produtos foram carregados, por meio de Declaração de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 1º A unidade emitente do Certificado Sanitário ou da Guia de Trânsito deve realizar a conferência da Declaração de Produtos de Origem Animal e dos seus documentos de respaldo anexados."}, {"c": "dou-paragraph", "t": "§ 2º A unidade emitente pode conferir os documentos de respaldo da certificação sanitária por amostragem, conforme diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 3º A solicitação do Certificado Sanitário ou da Guia de Trânsito à Unidade de Vigilância Agropecuária Internacional deve atender à legislação específica."}, {"c": "dou-paragraph", "t": "Art. 46. A conferência documental do Certificado Sanitário ou da Guia de Trânsito deve ser realizada por servidor do Ministério da Agricultura e Pecuária da unidade emitente."}, {"c": "dou-paragraph", "t": "§ 1º Esta conferência documental também pode ser realizada, de forma subsidiária e sob supervisão de servidor mencionado no caput, por:"}, {"c": "dou-paragraph", "t": "I - auxiliares e assistentes administrativos, contratados na forma da lei, nas Centrais de Certificação e nas Unidades de Vigilância Agropecuária Internacional; e"}, {"c": "dou-paragraph", "t": "II - auxiliares de inspeção, na equipe do serviço oficial no estabelecimento nacional, conforme a legislação."}, {"c": "dou-paragraph", "t": "§ 2º Esta conferência documental, realizada por auxiliares, é restrita à verificação de consistência de dados, integridade de registros e correspondência de informações, não compreendendo o juízo técnico-sanitário, a validação de conformidade do processo produtivo ou a avaliação de Requisitos Sanitários."}, {"c": "dou-paragraph", "t": "§ 3º A decisão sanitária, a validação técnico-legal e a emissão do Certificado Sanitário são de competência exclusiva do Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária, sendo proibida a sua delegação."}, {"c": "dou-paragraph", "t": "Art. 47. A emissão de documentos de trânsito é indeferida nos seguintes casos:"}, {"c": "dou-paragraph", "t": "I - preenchimento incorreto ou incompleto da Declaração de Produtos de Origem Animal de solicitação;"}, {"c": "dou-paragraph", "t": "II - preenchimento incorreto ou incompleto da Guia de Trânsito, do Certificado Sanitário Nacional ou do Certificado Sanitário Internacional;"}, {"c": "dou-paragraph", "t": "III - não apresentação ou apresentação parcial da documentação de respaldo de emissão do Certificado Sanitário ou da Guia de Trânsito;"}, {"c": "dou-paragraph", "t": "IV - apresentação de documentação de respaldo de emissão do Certificado Sanitário ou da Guia de Trânsito não conforme, com preenchimento incorreto, sem assinatura, com rasuras, ilegível ou sem identificação do emitente;"}, {"c": "dou-paragraph", "t": "V - seleção de modelo oficial do Certificado Sanitário ou da Guia de Trânsito incorreto para a finalidade ou o destino propostos;"}, {"c": "dou-paragraph", "t": "VI - solicitação do Certificado Sanitário ou da Guia de Trânsito à unidade emitente incorreta ou não autorizada a emitir certificação sanitária;"}, {"c": "dou-paragraph", "t": "VII - solicitação do Certificado Sanitário ou da Guia de Trânsito para produto, estabelecimento ou destino sob restrição ou impedimento;"}, {"c": "dou-paragraph", "t": "VIII - solicitação de emissão do Certificado Sanitário para produto ou estabelecimento não habilitado, conforme aplicável;"}, {"c": "dou-paragraph", "t": "IX - solicitação de emissão do Certificado Sanitário ou da Guia de Trânsito para motivos não previstos ou impedidos nesta portaria ou pelo Departamento de Inspeção de Produtos de Origem Animal;"}, {"c": "dou-paragraph", "t": "X - solicitação de cancelamento e de substituição do Certificado Sanitário ou da Guia de Trânsito para motivos não previstos ou impedidos nesta portaria; ou"}, {"c": "dou-paragraph", "t": "XI - outras não conformidades identificadas pelo serviço oficial."}, {"c": "dou-paragraph", "t": "Art. 48. A Guia de Trânsito deve ser emitida e assinada exclusivamente por Agente de Inspeção Sanitária e Industrial de Produtos de Origem Animal e pelos demais cargos efetivos de Atividades Técnicas de Fiscalização Federal Agropecuária, conforme a sua competência."}, {"c": "dou-paragraph", "t": "Art. 49. O Certificado Sanitário deve ser emitido e assinado exclusivamente por Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária."}, {"c": "dou-paragraph", "t": "§ 1º O Serviço de Inspeção Federal deve emitir Certificado Sanitário exclusivamente para produtos expedidos do estabelecimento nacional registrado no Departamento de Inspeção de Produtos de Origem Animal em caráter de inspeção permanente sob sua competência."}, {"c": "dou-paragraph", "t": "§ 2º Na impossibilidade do Serviço de Inspeção Federal emitir o Certificado Sanitário de que trata o § 1º, a emissão pode ser realizada em Central de Certificação, mediante autorização do Serviço de Inspeção de Produtos de Origem Animal da área de abrangência do estabelecimento nacional."}, {"c": "dou-paragraph", "t": "§ 3º Os estabelecimentos nacionais registrados no Departamento de Inspeção de Produtos de Origem Animal em caráter de inspeção periódica, devem solicitar o Certificado Sanitário em Central de Certificação."}, {"c": "dou-paragraph", "t": "§ 4º O disposto nos §§ 1º a 3º é aplicável para a emissão da Guia de Trânsito."}, {"c": "dou-paragraph", "t": "§ 5º A emissão do Certificado Sanitário pode ser realizada por Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária, tanto em atividade de inspeção como de fiscalização, em unidade de Vigilância Agropecuária Internacional, nos casos previstos nesta portaria."}, {"c": "dou-paragraph", "t": "§ 6º O Departamento de Inspeção de Produtos de Origem Animal pode autorizar a emissão de Certificados Sanitários em outras unidades administrativas do Ministério da Agricultura e Pecuária, como medida excepcional e por período estabelecido."}, {"c": "dou-paragraph", "t": "Art. 50. A emissão do Certificado Sanitário ou da Guia de Trânsito é realizada em sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 1º A emissão do Certificado Sanitário ou da Guia de Trânsito deve atender ao modelo oficial disponível no sistema informatizado, sendo proibida qualquer alteração de forma e conteúdo."}, {"c": "dou-paragraph", "t": "§ 2º O estabelecimento nacional deve atender as instruções de preenchimento do Certificado Sanitário ou da Guia de Trânsito disponíveis no sistema informatizado e nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária"}, {"c": "dou-paragraph", "t": "§ 3º Em caso de indisponibilidade temporária do sistema informatizado, a emissão pode ser realizada em medida de contingência, conforme estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 4º O Certificado Sanitário ou a Guia de Trânsito emitidos em medida de contingência, devem ser incluídos no sistema informatizado imediatamente após o retorno da sua disponibilidade."}, {"c": "dou-paragraph", "t": "Art. 51. O Certificado Sanitário Internacional deve ser emitido em vernáculo e em inglês, ou em vernáculo e no idioma do país importador, conforme exigência."}, {"c": "dou-paragraph", "t": "Parágrafo único. Quando os produtos tiverem trânsito por um país terceiro cujo idioma seja distinto daquele do país de destino, e este exigir a tradução do Certificado Sanitário Internacional, o responsável pela carga deve providenciar essa tradução."}, {"c": "dou-paragraph", "t": "Art. 52. A unidade emitente deve controlar a entrega do Certificado Sanitário ou da Guia de Trânsito ao solicitante."}, {"c": "dou-paragraph", "t": "Art. 53. A inclusão de informações comerciais no Certificado Sanitário Internacional é permitida somente com autorização do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 54. É permitida a emissão de Declaração Adicional anexa ao Certificado Sanitário Internacional por exigência da autoridade sanitária do país importador, conforme modelo oficial divulgado pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 1º É proibida a emissão de Declaração Adicional para país importador que possui modelo de Certificado Sanitário Internacional previamente acordado sem Declaração Adicional prevista, exceto se autorizada pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 2º É proibida qualquer alteração de forma e conteúdo da Declaração Adicional conforme modelo oficial divulgado pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 3º A Declaração Adicional é emitida via digital no sistema informatizado do Ministério da Agricultura e Pecuária, podendo ser de forma manual, em papel, quando autorizada pelo Departamento de Inspeção de Produtos de Origem Animal, com a mesma numeração e código de autenticidade do Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "§ 4º A Declaração Adicional deve atender as mesmas demais disposições para o Certificado Sanitário Internacional no que for aplicável, conforme esta portaria."}, {"c": "dou-paragraph", "t": "Art. 55. O Certificado Sanitário ou a Guia de Trânsito são considerados emitidos após a conferência das suas informações, a verificação do tachamento de texto se necessário, a sua impressão em papel, a aposição do carimbo datador e a assinatura pela autoridade do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 1º As assinaturas do Certificado Sanitário ou da Guia de Trânsito devem ser identificadas com carimbo padrão conforme estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º A assinatura e o carimbo do Auditor Fiscal Federal Agropecuário com formação em Medicina Veterinária, quando exigidos como avaliação de autenticidade do Certificado Sanitário Internacional por país importador, não podem ser alterados ou atualizados sem autorização do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 3º No caso de Certificado Sanitário ou de Guia de Trânsito emitidos exclusivamente via digital, estes são considerados emitidos após conferência das suas informações, a verificação do tachamento de texto se necessário e a assinatura pela autoridade do Ministério da Agricultura e Pecuária com certificado digital."}, {"c": "dou-paragraph", "t": "§ 4º No caso de Certificado Sanitário Internacional emitido exclusivamente via eletrônica, estes são considerados emitidos após a conferência das suas informações e o parecer no sistema informatizado pela autoridade do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 56. O Certificado Sanitário ou a Guia de Trânsito devem ser emitidos conforme estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. O Departamento de Inspeção de Produtos de Origem Animal deve estabelecer, conforme exigência da autoridade sanitária do país importador, quais modelos de Certificado Sanitário Internacional devem ser impressos em papel especial contendo elementos de segurança."}, {"c": "dou-paragraph", "t": "Art. 57. É proibida a solicitação do Certificado Sanitário ou da Guia de Trânsito em mais de uma unidade emitente para o mesmo carregamento de produtos."}, {"c": "dou-paragraph", "t": "Art. 58. Pode ser emitido mais de um Certificado Sanitário Internacional para um único contentor de carga de exportação, bem como pode ser emitido um único Certificado Sanitário Internacional para vários contentores de carga."}, {"c": "dou-paragraph", "t": "Art. 59. Os Certificados Sanitários e as Guias de Trânsito devem ser numerados de forma única, nacional e crescente, bem como devem ser gerados no sistema informatizado do Ministério da Agricultura e Pecuária, conforme estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. A lista contendo a relação da numeração e códigos de autenticidade a serem utilizados em medida de contingência caducará no primeiro dia do ano subsequente à sua emissão."}, {"c": "dou-paragraph", "t": "Art. 60. Nos casos em que não exista acordo bilateral firmado entre o Brasil e o país importador, com consequente ausência de modelo de certificado sanitário, o estabelecimento exportador deve verificar se a autoridade sanitária daquele destino autoriza a importação do produto com o Certificado Sanitário Internacional brasileiro."}, {"c": "dou-paragraph", "t": "Parágrafo único. Nos casos em que a autoridade sanitária do país importador aceite o Certificado Sanitário Internacional brasileiro, o estabelecimento nacional deve apresentar uma declaração junto à unidade emitente, responsabilizando-se integralmente pelo envio e internalização do produto naquele destino, para a emissão do Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "Art. 61. As Centrais de Certificação, com seus endereços e horários de funcionamento, estão disponíveis no sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. As Centrais de Certificação devem ser criadas ou extintas considerando:"}, {"c": "dou-paragraph", "t": "I - a demanda de Certificados Sanitários, ou de Guias de Trânsito, de uma determinada região;"}, {"c": "dou-paragraph", "t": "II - o pessoal disponível para atendimento;"}, {"c": "dou-paragraph", "t": "III - a existência de Unidade do Ministério da Agricultura e Pecuária, ou de outro órgão público, de quaisquer esferas da União, que possa ser compartilhada ou cedida, na forma da lei; e"}, {"c": "dou-paragraph", "t": "IV - a disponibilidade de equipamentos e materiais necessários para sua operacionalização."}, {"c": "dou-paragraph", "t": "Art. 62. No caso de a Central de Certificação encerrar suas atividades, os seus documentos devem ser direcionados a outra Central de Certificação, definida pelo Serviço de Inspeção de Produtos de Origem Animal da área de abrangência da central encerrada."}, {"c": "dou-paragraph", "t": "Subseção II"}, {"c": "dou-paragraph", "t": "Certificado Sanitário Nacional"}, {"c": "dou-paragraph", "t": "Art. 63. A emissão do Certificado Sanitário Nacional é obrigatória para o trânsito de produtos nas seguintes situações:"}, {"c": "dou-paragraph", "t": "I - quando destinados ao comércio internacional, de estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal, para:"}, {"c": "dou-paragraph", "t": "a) outro estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal, para país importador que exige habilitação;"}, {"c": "dou-paragraph", "t": "b) outro estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal, quando destinados ao aproveitamento condicional pelo serviço oficial ou para destinação industrial pelo estabelecimento, com processamento ou como matéria-prima de outros produtos para exportação, para país importador que exige habilitação;"}, {"c": "dou-paragraph", "t": "c) portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação para país importador que exige habilitação, com a certificação sanitária internacional realizada pela Unidade de Vigilância Agropecuária Internacional, seja:"}, {"c": "dou-paragraph", "t": "1. como carga solta ou fracionada, em porão de navio ou de aeronave; ou"}, {"c": "dou-paragraph", "t": "2. quando ocorrer a transferência do produto para o contentor de carga de exportação nestes locais."}, {"c": "dou-paragraph", "t": "d) estabelecimento registrado ou cadastrado em outro órgão fiscalizador, para processamento e posterior exportação, quando exigido pelo país importador."}, {"c": "dou-paragraph", "t": "II - de portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação, no caso de transferência de produtos não exportados, para estabelecimento nacional registrado no Departamento de Inspeção de Produtos de Origem Animal, quando não houver Certificado Sanitário Internacional vigente que respalde a carga ou o lacre não esteja intacto, tanto para país importador que exige ou não a habilitação;"}, {"c": "dou-paragraph", "t": "III - quando destinados pelo serviço oficial ao aproveitamento condicional ou condenação; e IV - para o trânsito de produtos não destinados ao mercado externo, nos casos estabelecidos pelo Departamento de Saúde Animal."}, {"c": "dou-paragraph", "t": "§ 1º A Guia de Trânsito pode ser emitida em substituição ao Certificado Sanitário Nacional nos casos previstos nos incisos III e IV, desde que os produtos não se destinem ao mercado externo."}, {"c": "dou-paragraph", "t": "§ 2º Não se aplica o disposto no inciso III para os resíduos de abate de animais, incluídos os casos em que não for possível separar o material condenado oriundo do Departamento de Inspeção Final e das linhas de inspeção post mortem do material condenado pelo estabelecimento de abate nas demais operações industriais, e o trânsito desses produtos deve ser respaldado por Declaração de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 3º Para os casos de que trata o inciso I, alínea d, o estabelecimento registrado em outro órgão fiscalizador deve encaminhar ao estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal uma declaração que conste a legislação ou exigência do país importador, que respalde a emissão do Certificado Sanitário Nacional."}, {"c": "dou-paragraph", "t": "§ 4º O disposto neste artigo se aplica ao trânsito de produtos destinados a processamento ou como matéria-prima de outros produtos para exportação, garantindo a sua rastreabilidade."}, {"c": "dou-paragraph", "t": "Art. 64. Para os contentores carregados conjuntamente com produtos destinados a país importador que não exige habilitação e para país importador que exige habilitação, deve ser emitido um Certificado Sanitário Nacional respaldando toda a carga de produtos."}, {"c": "dou-paragraph", "t": "Art. 65. O estabelecimento nacional deve comprovar o seu recebimento dos produtos destinados ao aproveitamento condicional ou à condenação junto à unidade emitente do Certificado Sanitário Nacional de respaldo."}, {"c": "dou-paragraph", "t": "Subseção III"}, {"c": "dou-paragraph", "t": "Certificado Sanitário Internacional"}, {"c": "dou-paragraph", "t": "Art. 66. A emissão do Certificado Sanitário Internacional é obrigatória para o trânsito de produtos para exportação nas seguintes situações:"}, {"c": "dou-paragraph", "t": "I - de estabelecimento registrado no Departamento de Inspeção de Produtos de Origem Animal para portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação com Unidade de Vigilância Agropecuária Internacional;"}, {"c": "dou-paragraph", "t": "II - de portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação, com Unidade de Vigilância Agropecuária Internacional, quando destinados à exportação como carga solta em porão de navio ou de aeronave ou quando ocorrer a transferência do produto para o contentor de carga de exportação nesses locais; e"}, {"c": "dou-paragraph", "t": "III - de portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação com Unidade de Vigilância Agropecuária Internacional, nos casos de contentores de carga submetidos a vistoria física, pela autoridade aduaneira ou por outros órgãos de fiscalização, nos casos de país importador que não aceite o carimbo de reinspeção no Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "§ 1º A emissão do Certificado Sanitário Internacional para país importador que exige habilitação é respaldada por Certificado Sanitário Nacional."}, {"c": "dou-paragraph", "t": "§ 2º A emissão de Certificado Sanitário Internacional para país importador que não exige habilitação é respaldada por Declaração de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 3º Para os casos previstos no art. 35, inciso II, alínea e, a emissão de Certificado Sanitário Internacional é respaldada pela Declaração de Produtos de Origem Animal que respaldou o trânsito de retorno da carga e pelo Certificado Sanitário Internacional emitido anteriormente."}, {"c": "dou-paragraph", "t": "§ 4º Para os casos previstos no inciso III do caput, a emissão do certificado sanitário internacional deve ser realizada pela unidade de Vigilância Agropecuária Internacional, mediante a substituição do certificado sanitário internacional que acompanhou o trânsito dos produtos, o qual respalda a certificação."}, {"c": "dou-paragraph", "t": "§ 5º Para os casos previstos no inciso II do caput, a emissão do certificado sanitário internacional deve ser realizada no estabelecimento sob Serviço de Inspeção Federal, quando em caráter de inspeção permanente ou em centrais de certificação nos demais casos, desde que:"}, {"c": "dou-paragraph", "t": "I - não seja necessário informar os números de lacre no Certificado Sanitário Internacional;"}, {"c": "dou-paragraph", "t": "II - não seja necessário o uso de lacres oficiais nas embalagens, contentores, veículos ou outros meios, que devam ser informados no Certificado Sanitário Internacional, devido à fiscalização do transbordo pela Vigilância Agropecuária Internacional; ou"}, {"c": "dou-paragraph", "t": "III - os produtos sejam expedidos do estabelecimento nacional acondicionados em volumes individuais, caixas, tambores ou embalagens similares, com lacres do Serviço de Inspeção Federal, que constem no Certificado Sanitário Internacional, e desde que estes lacres não sejam rompidos devido à fiscalização do transbordo pela Vigilância Agropecuária Internacional."}, {"c": "dou-paragraph", "t": "§ 6º Para os casos previstos no inciso II, do caput, a Unidade de Vigilância Agropecuária Internacional emite o Certificado Sanitário Internacional para os casos de transferência do produto para o contentor de carga de exportação e para a exportação em porão de navio nos portos."}, {"c": "dou-paragraph", "t": "Art. 67. É proibida a exportação de produto sem o Certificado Sanitário Internacional correspondente."}, {"c": "dou-paragraph", "t": "§ 1º Caso seja realizada a exportação de que trata o caput, o produto envolvido deve ser desabilitado, sendo proibida a emissão do seu Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "§ 2º O produto de que trata o § 1º que retornar ao Brasil deve ser submetido à reinspeção e destinação pelo serviço oficial, sem prejuízo das demais ações fiscais cabíveis junto ao estabelecimento nacional exportador."}, {"c": "dou-paragraph", "t": "§ 3º O caput deste artigo não se aplica se a autoridade sanitária do país importador não exigir a emissão do Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Substituição e cancelamento da Declaração de Produtos de Origem Animal, da Guia De Trânsito e do Certificado Sanitário"}, {"c": "dou-paragraph", "t": "Subseção I"}, {"c": "dou-paragraph", "t": "Substituição e cancelamento da Declaração de Produtos de Origem Animal"}, {"c": "dou-paragraph", "t": "Art. 68. A substituição ou o cancelamento da Declaração de Produtos de Origem Animal é permitida, com controle das suas alterações pelo estabelecimento nacional emissor e desde que não haja contradição com as informações declaradas anteriormente."}, {"c": "dou-paragraph", "t": "§ 1º A manutenção da rastreabilidade e da segurança sanitária do produto deve ser comprovada com registros auditáveis."}, {"c": "dou-paragraph", "t": "§ 2º A substituição da Declaração de Produtos de Origem Animal deve ser realizada dentro do seu prazo de validade para trânsito, à exceção do disposto no art. 94, § 3º."}, {"c": "dou-paragraph", "t": "§ 3º A substituição da Declaração de Produtos de Origem Animal é permitida para alteração do país importador de destino ou do destinatário, desde que atendidos os Requisitos Sanitários e ao disposto no art. 94, § 3º."}, {"c": "dou-paragraph", "t": "Art. 69. Os estabelecimentos devem realizar o controle e a avaliação crítica dos motivos das substituições das Declarações de Produtos de Origem Animal emitidas por meio de registros auditáveis."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os estabelecimentos devem prever, em seus programas de autocontrole, medidas corretivas e preventivas para prevenir as substituições causadas por erros de procedimento."}, {"c": "dou-paragraph", "t": "Art. 70. A Declaração de Produtos de Origem Animal já emitida somente pode ser cancelada quando:"}, {"c": "dou-paragraph", "t": "I - o trânsito tenha deixado de ocorrer, permanecendo a carga armazenada no estabelecimento nacional;"}, {"c": "dou-paragraph", "t": "II - não tenha sido utilizada para solicitar a emissão do Certificado Sanitário ou da Guia de Trânsito;"}, {"c": "dou-paragraph", "t": "III - o Certificado Sanitário ou a Guia de Trânsito solicitados tenham sido cancelados; ou"}, {"c": "dou-paragraph", "t": "IV - ocorrer redirecionamento para mercado interno enquanto os produtos estão em trânsito nacional."}, {"c": "dou-paragraph", "t": "Parágrafo único. A Declaração de Produtos de Origem Animal não pode ser cancelada quando já tiver respaldado o trânsito dos produtos de origem animal."}, {"c": "dou-paragraph", "t": "Art. 71. A Declaração de Produtos de Origem Animal deve ser substituída ou cancelada em sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 72. Para a substituição do Certificado Sanitário ou da Guia de Trânsito deve ser substituída a Declaração de Produtos de Origem Animal de solicitação do Certificado Sanitário ou da Guia de Trânsito a serem substituídos."}, {"c": "dou-paragraph", "t": "Parágrafo único. A Declaração de Produtos de Origem Animal substituta de que trata o caput deve ser utilizada para solicitar o Certificado Sanitário ou a Guia de Trânsito a serem substituídos."}, {"c": "dou-paragraph", "t": "Art. 73. É proibida a substituição ou o cancelamento de Declaração de Produtos de Origem Animal, emitida para o trânsito de produtos para exportação, por Certificado Sanitário Nacional."}, {"c": "dou-paragraph", "t": "Subseção II"}, {"c": "dou-paragraph", "t": "Substituição e cancelamento da Guia de Trânsito e do Certificado Sanitário"}, {"c": "dou-paragraph", "t": "Art. 74. A substituição ou o cancelamento do Certificado Sanitário ou da Guia de Trânsito são permitidos mediante a solicitação do estabelecimento nacional à unidade emitente do Certificado Sanitário ou da Guia de Trânsito a serem substituídos ou cancelados."}, {"c": "dou-paragraph", "t": "§ 1º O estabelecimento nacional deve apresentar o Certificado Sanitário ou a Guia de Trânsito originais, a justificativa e as medidas corretivas adotadas, conforme seu programa de autocontrole, bem como atender as demais instruções nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º A unidade emitente deve analisar a solicitação de que trata o caput e pode requerer informações e documentação complementares."}, {"c": "dou-paragraph", "t": "§ 3º Se o Certificado Sanitário ou a Guia de Trânsito originais, não puderem ser apresentados imediatamente, o estabelecimento nacional tem o prazo de trinta dias para a sua apresentação à unidade emitente."}, {"c": "dou-paragraph", "t": "Art. 75. A substituição ou o cancelamento do Certificado Sanitário Nacional é permitida, com controle das suas alterações pelo estabelecimento nacional emissor e desde que não haja contradição das informações com o respectivo Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "Art. 76. A substituição do Certificado Sanitário Internacional pode ser feita com o carregamento tanto em trânsito nacional como em trânsito internacional."}, {"c": "dou-paragraph", "t": "Art. 77. O Certificado Sanitário ou a Guia de Trânsito substitutos devem apresentar a frase de cronologia de substituição, gerada pelo sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 78. O Certificado Sanitário ou a Guia de Trânsito substituídos no sistema informatizado do Ministério da Agricultura e Pecuária, devem ter suas vias \"original\" e \"cópia\" substituídas e arquivadas na unidade emitente."}, {"c": "dou-paragraph", "t": "§ 1º Deve ser aposto o carimbo \"SUBSTITUÍDO\", conforme modelo estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º O Certificado Sanitário ou a Guia de Trânsito substituídos não podem ser cancelados, porque são os documentos de respaldo de emissão dos novos Certificado Sanitário ou Guia de Trânsito."}, {"c": "dou-paragraph", "t": "Art. 79. O Certificado Sanitário ou a Guia de Trânsito cancelados no sistema informatizado, do Ministério da Agricultura e Pecuária devem ter suas vias \"original\" e \"cópia\" canceladas e arquivadas na unidade emitente."}, {"c": "dou-paragraph", "t": "Parágrafo único. Deve ser aposto o carimbo \"CANCELADO\" nas respectivas vias, conforme modelo estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 80. O Certificado Sanitário ou a Guia de Trânsito somente podem ser cancelados nos seguintes casos:"}, {"c": "dou-paragraph", "t": "I - quando já possuírem o parecer de aprovação pela unidade emitente, porém o trânsito não tenha ocorrido, permanecendo a carga armazenada no estabelecimento nacional; ou"}, {"c": "dou-paragraph", "t": "II - quando houver redirecionamento da carga para o mercado interno, enquanto em trânsito nacional."}, {"c": "dou-paragraph", "t": "Parágrafo único. O Certificado Sanitário ou a Guia de Trânsito não podem ser cancelados quando já tiverem respaldado o trânsito dos Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 81. A substituição do Certificado Sanitário ou da Guia de Trânsito pode ocorrer em unidade emitente diferente da unidade emitente original nos seguintes casos:"}, {"c": "dou-paragraph", "t": "I - para emissão de Certificado Sanitário Internacional realizada pela Vigilância Agropecuária Internacional, nos casos de país importador que não aceite o carimbo de reinspeção no Certificado Sanitário Internacional; ou"}, {"c": "dou-paragraph", "t": "II - outros, mediante análise e autorização do Serviço de Inspeção de Produtos de Origem Animal da área de abrangência do estabelecimento nacional."}, {"c": "dou-paragraph", "t": "§ 1º O Serviço de Inspeção de Produtos de Origem Animal da área de abrangência do estabelecimento nacional deve comunicar à unidade emitente responsável pela substituição do Certificado Sanitário ou da Guia de Trânsito sobre a autorização do procedimento, via processo administrativo."}, {"c": "dou-paragraph", "t": "§ 2º O estabelecimento nacional deve comunicar este procedimento à unidade emitente do Certificado Sanitário ou da Guia de Trânsito substituída, apresentando cópia do documento substituto, para aposição do carimbo \"SUBSTITUÍDO\", conforme modelo estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 3º O estabelecimento nacional exportador deve apresentar os documentos de que trata o § 2º, no prazo de trinta dias, contados a partir da data de emissão do Certificado Sanitário ou da Guia de Trânsito substitutos."}, {"c": "dou-paragraph", "t": "Art. 82. A Carta de Correção pode ser emitida em vez da substituição do Certificado Sanitário Internacional nos seguintes casos:"}, {"c": "dou-paragraph", "t": "I - para cargas que já tenham saído do território nacional;"}, {"c": "dou-paragraph", "t": "II - para correção de no máximo dois itens do Certificado Sanitário Internacional; e"}, {"c": "dou-paragraph", "t": "III - para país importador que aceite a Carta de Correção."}, {"c": "dou-paragraph", "t": "§ 1º A Carta de Correção deve ser apresentada em modelo estabelecido pelo Departamento de Inspeção de Produtos de Origem Animal, sem alterações de forma ou conteúdo."}, {"c": "dou-paragraph", "t": "§ 2º Os itens do Certificado Sanitário Internacional passíveis de correção por Carta de Correção serão estabelecidos nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 3º A Carta de Correção substituta deve, obrigatoriamente, apresentar a frase de cronologia de substituição, gerada pelo sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 83. A solicitação de substituição do Certificado Sanitário ou da Guia de Trânsito, bem como da Carta de Correção, deve ser realizada em sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Subseção III"}, {"c": "dou-paragraph", "t": "Substituição da Guia de Trânsito, do Certificado Sanitário e da Carta de Correção por extravio"}, {"c": "dou-paragraph", "t": "Art. 84. Em caso de extravio, o Certificado Sanitário ou a Guia de Trânsito, bem como a Carta de Correção, somente podem ser substituídos com a apresentação da Declaração de Extravio, pelo estabelecimento nacional, acompanhada de Boletim de Ocorrência emitido junto à autoridade policial brasileira."}, {"c": "dou-paragraph", "t": "§ 1º A Declaração de Extravio deve ser apresentada em modelo estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º Os documentos de que trata o caput devem ser apresentados em sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 85. O Certificado Sanitário ou a Guia de Trânsito, bem como a Carta de Correção, substituídos no sistema informatizado do Ministério da Agricultura e Pecuária, devem ter sua via \"cópia\" arquivada na unidade emitente."}, {"c": "dou-paragraph", "t": "Parágrafo único. Deve ser aposto o carimbo \"SUBSTITUÍDO\" na respectiva via, conforme modelo estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 86. Caso o Certificado Sanitário ou a Guia de Trânsito extraviados referentes a cargas que se encontrem em território nacional, tenham perdido o prazo de validade, deve ser realizada a reinspeção oficial em estabelecimento nacional registrado no Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Parágrafo único. O Certificado Sanitário Internacional extraviado, de cargas que saíram do território nacional, pode ser substituído desde que esteja dentro do seu prazo de validade."}, {"c": "dou-paragraph", "t": "Seção IV"}, {"c": "dou-paragraph", "t": "Trânsito de amostra sem valor comercial"}, {"c": "dou-paragraph", "t": "Art. 87. A exportação de amostras sem valor comercial pode ser realizada para os seguintes fins:"}, {"c": "dou-paragraph", "t": "I - amostras biológicas, destinadas à realização de análises laboratoriais, aos diagnósticos e investigação no âmbito da medicina humana ou animal, na indústria farmacêutica, cosmética ou de produtos sanitários;"}, {"c": "dou-paragraph", "t": "II - amostras destinadas a feiras, eventos diplomáticos, congressos, exposições ou avaliações comerciais, que possam implicar ou não no consumo humano; ou"}, {"c": "dou-paragraph", "t": "III - amostras para a realização de provas de equipamentos e maquinários na indústria alimentícia, que possam implicar ou não no consumo humano."}, {"c": "dou-paragraph", "t": "Art. 88. Somente podem ser exportadas amostras sem valor comercial de produtos de estabelecimentos nacionais registrados no Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 89. Para a emissão de Certificado Sanitário ou de outro documento exigido pela autoridade sanitária do país importador, o estabelecimento nacional deve apresentar a Declaração de Exportação de amostras sem valor comercial dos produtos, com os documentos de respaldo."}, {"c": "dou-paragraph", "t": "Parágrafo único. A Declaração de Exportação de amostras sem valor comercial dos produtos deve ser apresentada em modelo estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 90. Os produtos exportados como amostra sem valor comercial devem apresentar sua rotulagem de acordo com as exigências do país importador."}, {"c": "dou-paragraph", "t": "§ 1º Na ausência das exigências de rotulagem para amostras sem valor comercial pelo país importador, a embalagem deve apresentar as seguintes informações, conforme a sua finalidade:"}, {"c": "dou-paragraph", "t": "I - feiras, eventos diplomáticos, congressos, exposições ou avaliações comerciais: \"amostra sem valor comercial apta ao consumo humano - venda proibida\" ou \"amostra sem valor comercial não apta ao consumo humano - venda proibida\";"}, {"c": "dou-paragraph", "t": "II - biológica: \"amostra biológica, não apta ao consumo humano - venda proibida\"; ou"}, {"c": "dou-paragraph", "t": "III - provas de equipamentos e maquinários: \"amostra para provas de equipamentos, apta ao consumo humano, venda proibida\" ou \"amostra para provas de equipamentos, não apta ao consumo humano, venda proibida\"."}, {"c": "dou-paragraph", "t": "§ 2º A informação de identificação da amostra sem valor comercial de que tratam os incisos I ao III do § 1º deve ser aposta na embalagem por meio de etiqueta complementar ou impressão indelével, sem sobreposição das informações contidas no rótulo."}, {"c": "dou-paragraph", "t": "Art. 91. O volume, o peso ou a quantidade dos produtos que podem ser autorizados à exportação como amostra sem valor comercial depende da sua finalidade."}, {"c": "dou-paragraph", "t": "Seção V"}, {"c": "dou-paragraph", "t": "Responsabilidade do exportador"}, {"c": "dou-paragraph", "t": "Art. 92. Sem prejuízo das demais disposições desta portaria, é responsabilidade do exportador:"}, {"c": "dou-paragraph", "t": "I - verificar as regras do país importador para o envio de produtos ou amostras sem valor comercial que devem ser atendidas, como:"}, {"c": "dou-paragraph", "t": "a) emissão de licença de importação;"}, {"c": "dou-paragraph", "t": "b) necessidade de emissão de Certificado Sanitário, Declaração Sanitária, ou outro documento;"}, {"c": "dou-paragraph", "t": "c) existência de modelo de Certificado Sanitário Internacional acordado para a exportação do produto, de modelo acordado para amostras sem valor comercial ou aceitação do modelo de Certificado Sanitário Internacional brasileiro; e"}, {"c": "dou-paragraph", "t": "d) necessidade de habilitação do estabelecimento."}, {"c": "dou-paragraph", "t": "II - preencher a Declaração de Exportação de amostras sem valor comercial, quando aplicável;"}, {"c": "dou-paragraph", "t": "III - o cumprimento das regras de transporte, embalagem, lacração, registro de produtos e rotulagem estabelecidos na legislação nacional, bem como as exigidas pelo país importador; e"}, {"c": "dou-paragraph", "t": "IV - o cumprimento dos requisitos sanitários e demais requisitos de importação do país importador."}, {"c": "dou-paragraph", "t": "Art. 93. O estabelecimento nacional é responsável pelas informações incluídas nos documentos de trânsito, bem como pela seleção do modelo do Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "Parágrafo único. O serviço oficial pode adotar as sanções previstas em legislação quanto às inconsistências apresentadas."}, {"c": "dou-paragraph", "t": "Seção VI"}, {"c": "dou-paragraph", "t": "Prazo de validade da Declaração de Produtos de Origem Animal, da Guia de Trânsito e dos Certificados Sanitários"}, {"c": "dou-paragraph", "t": "Art. 94. A Declaração de Produtos de Origem Animal, a Guia de Trânsito e os Certificados Sanitários têm os seguintes prazos de validade para o trânsito até o destino:"}, {"c": "dou-paragraph", "t": "I - trinta dias para Declaração de Produtos de Origem Animal, Guia de Trânsito e o Certificado Sanitário Nacional; e"}, {"c": "dou-paragraph", "t": "II - cento e oitenta dias para o Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "§ 1º A Declaração de Produtos de Origem Animal, a Guia de Trânsito e os Certificados Sanitários substitutos têm a mesma data de validade da Declaração de Produtos de Origem Animal, da Guia de Trânsito e dos Certificados Sanitários que estão substituindo."}, {"c": "dou-paragraph", "t": "§ 2º A data de validade de que trata o caput conta a partir da data de emissão da Declaração de Produtos de Origem Animal, da Guia de Trânsito e dos Certificados Sanitários."}, {"c": "dou-paragraph", "t": "§ 3º A Declaração de Produtos de Origem Animal pode ser substituída, após o prazo de validade de trânsito ter vencido, somente para a inclusão de país importador, e desde que:"}, {"c": "dou-paragraph", "t": "I - o trânsito do produto tenha ocorrido dentro do prazo de validade da declaração; e"}, {"c": "dou-paragraph", "t": "II - atendidos os requisitos sanitários do país importador a ser incluído."}, {"c": "dou-paragraph", "t": "Seção VII"}, {"c": "dou-paragraph", "t": "Revalidação do prazo de validade da Declaração de Produtos de Origem Animal, da Guia de Trânsito e dos Certificados Sanitários"}, {"c": "dou-paragraph", "t": "Art. 95. O Certificado Sanitário Internacional pode ter seu prazo de validade revalidado por mais cento e oitenta dias, quando houver o redirecionamento de produtos em trânsito internacional para outro destinatário ou país importador."}, {"c": "dou-paragraph", "t": "§ 1º A revalidação do prazo de validade deve ser realizada com a substituição do respectivo Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "§ 2º A revalidação pode ser solicitada uma única vez."}, {"c": "dou-paragraph", "t": "§ 3º A solicitação de substituição para a revalidação do prazo de validade do Certificado Sanitário Internacional deve ser realizada dentro do prazo de validade do Certificado Sanitário Internacional a ser substituído."}, {"c": "dou-paragraph", "t": "Art. 96. O não atendimento do prazo estabelecido para a solicitação do novo Certificado Sanitário Internacional implicará:"}, {"c": "dou-paragraph", "t": "I - no retorno do produto ao Brasil para reinspeção oficial;"}, {"c": "dou-paragraph", "t": "II - no atendimento à destinação determinada pela autoridade sanitária do país importador; ou"}, {"c": "dou-paragraph", "t": "III - em outro redirecionamento estabelecido pelo estabelecimento nacional exportador, desde que aceito pela autoridade sanitária do país importador e não implique na necessidade de substituição do Certificado Sanitário Internacional vencido."}, {"c": "dou-paragraph", "t": "Art. 97. A Declaração de Produtos de Origem Animal, a Guia de Trânsito e o Certificado Sanitário Nacional, substitutos dos respectivos vencidos, devem apresentar a frase \"SUBSTITUIÇÃO PARA REVALIDAÇÃO DO PRAZO DE VALIDADE\" no seu campo de \"observações\"."}, {"c": "dou-paragraph", "t": "Seção VIII"}, {"c": "dou-paragraph", "t": "Reinspeção oficial e revisão de autocontrole"}, {"c": "dou-paragraph", "t": "Art. 98. A reinspeção oficial deve ser realizada:"}, {"c": "dou-paragraph", "t": "I - por solicitação do estabelecimento nacional ao serviço oficial; ou"}, {"c": "dou-paragraph", "t": "II - por solicitação do serviço oficial responsável pela emissão do Certificado Sanitário ou da Guia de Trânsito, ou em fiscalização no estabelecimento nacional, para avaliação da carga."}, {"c": "dou-paragraph", "t": "Parágrafo único. O estabelecimento nacional deve solicitar a reinspeção oficial com antecedência mínima de setenta e duas horas em relação à data prevista para o recebimento dos produtos."}, {"c": "dou-paragraph", "t": "Art. 99. A reinspeção oficial deve ser realizada nas cargas em trânsito nacional com lacre violado ou com documento de trânsito com prazo de validade vencido."}, {"c": "dou-paragraph", "t": "§ 1º As cargas de que trata o caput devem ser redirecionadas a estabelecimento nacional registrado no Departamento de Inspeção de Produtos de Origem Animal para a reinspeção oficial."}, {"c": "dou-paragraph", "t": "§ 2º A reinspeção oficial nas cargas com lacre violado somente pode ser autorizada após a apresentação de documento comprobatório emitido pela autoridade fiscalizadora responsável pelo rompimento do lacre ou de documento emitido pelo estabelecimento nacional com a justificativa da violação."}, {"c": "dou-paragraph", "t": "Art. 100. A reinspeção oficial pode ser dispensada no caso de cargas de produtos nacionais exportados e devolvidos ao Brasil por motivos comerciais, a critério do serviço oficial, conforme avaliação documental."}, {"c": "dou-paragraph", "t": "Parágrafo único. Em caso de dispensa da reinspeção oficial, o estabelecimento nacional deve realizar a revisão de autocontrole, com registros auditáveis."}, {"c": "dou-paragraph", "t": "Art. 101. A revisão de autocontrole deve ser realizada:"}, {"c": "dou-paragraph", "t": "I - no caso de cargas de produtos nacionais exportados e devolvidos ao Brasil por motivos comerciais, com dispensa da reinspeção oficial; ou"}, {"c": "dou-paragraph", "t": "II - no caso de cargas em trânsito nacional, com documentos de trânsito, que não tenham realizado o trânsito previsto por evento adverso, incluindo, mas não se limitando a casos de acidentes."}, {"c": "dou-paragraph", "t": "§ 1º As cargas de que trata o caput devem ser redirecionadas a estabelecimento nacional registrado no Departamento de Inspeção de Produtos de Origem Animal para a revisão de autocontrole."}, {"c": "dou-paragraph", "t": "§ 2º O estabelecimento de origem deve solicitar a revisão de autocontrole ao estabelecimento responsável pela recepção dos produtos, onde deve ser realizada a avaliação desses produtos."}, {"c": "dou-paragraph", "t": "Art. 102. A revisão de autocontrole deve estar contemplada nos programas de autocontrole do estabelecimento nacional, mantendo registros auditáveis."}, {"c": "dou-paragraph", "t": "Art. 103. A reinspeção oficial e a revisão de autocontrole devem ser registradas em formulário, conforme modelos estabelecidos nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Seção IX"}, {"c": "dou-paragraph", "t": "Trânsito de produto com laudo laboratorial pendente"}, {"c": "dou-paragraph", "t": "Art. 104. É proibida a emissão de Certificado Sanitário Internacional para produtos pendentes de laudo laboratorial exigido como respaldo."}, {"c": "dou-paragraph", "t": "§ 1º O trânsito de produtos pendentes de laudo laboratorial somente é permitido se acompanhados de Declaração de Produtos de Origem Animal ou Certificado Sanitário Nacional, entre estabelecimentos registrados no Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "§ 2º A pendência de laudo laboratorial deve estar identificada na Declaração de Produtos de Origem Animal ou no Certificado Sanitário Nacional."}, {"c": "dou-paragraph", "t": "Art. 105. O Responsável Técnico ou o responsável pelo Controle de Qualidade do estabelecimento nacional deve incluir o laudo laboratorial exigido como respaldo do Certificado Sanitário Internacional no sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Parágrafo único. O estabelecimento nacional deve verificar se o resultado do laudo laboratorial está em conformidade para o respaldo do Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "Art. 106. Em caso de o resultado do laudo laboratorial se apresentar não conforme com a legislação nacional ou do país importador, o estabelecimento deve realizar a segregação e destinação dos produtos, mantendo registros de autocontrole auditáveis."}, {"c": "dou-paragraph", "t": "Seção X"}, {"c": "dou-paragraph", "t": "Lacre e etiqueta lacre"}, {"c": "dou-paragraph", "t": "Art. 107. O estabelecimento nacional deve lacrar as cargas de produtos para emissão da Declaração de Produtos de Origem Animal, do Certificado Sanitário ou da Guia de Trânsito, garantindo a sua inviolabilidade e rastreabilidade."}, {"c": "dou-paragraph", "t": "§ 1º Podem ser utilizados lacres para produtos exportados em volumes individuais, em caixas, tambores ou embalagens similares, conforme modelo estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º A lacração de veículos, contêineres ou outros contentores de trânsito de produtos pode ser dispensada a critério do Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 108. O lacre deve ser identificado por numeração de forma sequencial, conforme modelo padronizado na legislação pertinente."}, {"c": "dou-paragraph", "t": "Art. 109. Na Declaração de Produtos de Origem Animal, no Certificado Sanitário, na Guia de Trânsito ou em outros documentos, a descrição do lacre deve apresentar:"}, {"c": "dou-paragraph", "t": "I - a sua sequência de identificação numérica, separada por barra da sigla \"SIF\" e seguida do número de registro do estabelecimento nacional; ou"}, {"c": "dou-paragraph", "t": "II - a sua sequência de identificação numérica separada por barra e seguida da sigla \"VIGIAGRO\", para as cargas lacradas na Unidade de Vigilância Agropecuária Internacional."}, {"c": "dou-paragraph", "t": "Art. 110. O estabelecimento nacional deve manter registros de autocontrole de estoque dos lacres e das etiquetas-lacres, bem como da lacração dos contêineres ou outros contentores de trânsito de produtos."}, {"c": "dou-paragraph", "t": "Seção XI"}, {"c": "dou-paragraph", "t": "Redirecionamento"}, {"c": "dou-paragraph", "t": "Art. 111. Os produtos destinados à exportação podem ter seu trânsito redirecionado nos seguintes casos:"}, {"c": "dou-paragraph", "t": "I - para alteração do destinatário ou do país de destino; ou"}, {"c": "dou-paragraph", "t": "II - para o mercado interno, nacional."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os procedimentos de redirecionamento dos produtos devem estar descritos em programas de autocontrole."}, {"c": "dou-paragraph", "t": "Subseção I"}, {"c": "dou-paragraph", "t": "Redirecionamento para alteração de destinatário ou de país de destino"}, {"c": "dou-paragraph", "t": "Art. 112. O redirecionamento para alteração do destinatário ou do país de destino é permitido desde que para:"}, {"c": "dou-paragraph", "t": "I - o mesmo país importador; ou"}, {"c": "dou-paragraph", "t": "II - país importador com requisito sanitário semelhante ou menos restritivo, conforme o Certificado Sanitário Internacional previamente emitido."}, {"c": "dou-paragraph", "t": "Art. 113. O redirecionamento é realizado com a substituição do Certificado Sanitário Internacional previamente emitido."}, {"c": "dou-paragraph", "t": "§ 1º A alteração do destinatário pode ser realizada com Carta de Correção, desde que aceita pelo país importador e o produto já tenha saído do território nacional."}, {"c": "dou-paragraph", "t": "§ 2º Se o Certificado Sanitário Internacional ainda não foi emitido, a Declaração de Produtos de Origem Animal ou o Certificado Sanitário Nacional de respaldo devem ser substituídos, para respaldar a certificação sanitária."}, {"c": "dou-paragraph", "t": "§ 3º A substituição da Declaração de Produtos de Origem Animal ou do Certificado Sanitário Nacional de respaldo da certificação sanitária é dispensada se o produto já estiver respaldado por Certificado Sanitário Internacional."}, {"c": "dou-paragraph", "t": "§ 4º O Certificado Sanitário Internacional de que trata o caput é o documento de respaldo para a certificação sanitária, não podendo ser cancelado."}, {"c": "dou-paragraph", "t": "Art. 114. A solicitação de redirecionamento deve ser realizada pelo estabelecimento nacional exportador dentro do prazo de validade do Certificado Sanitário Internacional que acompanha o carregamento."}, {"c": "dou-paragraph", "t": "Art. 115. O estabelecimento deve verificar a necessidade de habilitação do produto para o país importador pretendido."}, {"c": "dou-paragraph", "t": "Subseção II"}, {"c": "dou-paragraph", "t": "Redirecionamento para mercado interno"}, {"c": "dou-paragraph", "t": "Art. 116. Os produtos destinados à exportação, em trânsito, em estoque ou localizados em portos, aeroportos, postos de fronteira, aduanas especiais ou recintos especiais de despacho aduaneiro de exportação possuem livre comercialização e trânsito no território nacional, podendo ser redirecionados para o mercado interno, desde que atendidos os seguintes critérios:"}, {"c": "dou-paragraph", "t": "I - o produto, na forma como se apresenta, deve atender à legislação nacional; e"}, {"c": "dou-paragraph", "t": "II - o produto deve estar dentro do seu prazo de validade, indicado na rotulagem."}, {"c": "dou-paragraph", "t": "§ 1º Os produtos devem ter a Declaração de Produtos de Origem Animal ou o Certificado Sanitário Nacional cancelados se estiverem em trânsito nacional."}, {"c": "dou-paragraph", "t": "§ 2º Os produtos que não atendam aos requisitos para redirecionamento ao mercado interno devem ser destinados:"}, {"c": "dou-paragraph", "t": "I - à destinação industrial;"}, {"c": "dou-paragraph", "t": "II - ao comércio institucional;"}, {"c": "dou-paragraph", "t": "III - à condenação; ou"}, {"c": "dou-paragraph", "t": "IV - à inutilização."}, {"c": "dou-paragraph", "t": "§ 3º A destinação ao comércio institucional pode ser realizada mesmo que os produtos apresentem rotulagem que não atenda à legislação nacional."}, {"c": "dou-paragraph", "t": "§ 4º A destinação ao comércio institucional deve ser realizada com a apresentação de um termo de compromisso firmado entre comprador e vendedor, garantindo que os produtos não serão direcionados ao consumidor final na forma em que se apresentam, conforme modelo estabelecido nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 117. O estabelecimento nacional deve manter registros auditáveis do redirecionamento, incluindo:"}, {"c": "dou-paragraph", "t": "I - o redirecionamento dos produtos para o mercado interno;"}, {"c": "dou-paragraph", "t": "II - a destinação industrial;"}, {"c": "dou-paragraph", "t": "III - a destinação para o comércio institucional;"}, {"c": "dou-paragraph", "t": "IV - a condenação; e"}, {"c": "dou-paragraph", "t": "V - a inutilização."}, {"c": "dou-paragraph", "t": "Parágrafo único. A solicitação de cancelamento dos documentos de trânsito deve ser anexada aos registros citados nos incisos I a V, quando houver."}, {"c": "dou-paragraph", "t": "Art. 118. Os produtos reimportados, quando em trânsito de portos, aeroportos e postos de fronteira para estabelecimentos nacionais registrados no Departamento de Inspeção de Produtos de Origem Animal, devem transitar acompanhados de documento emitido pela Unidade de Vigilância Agropecuária Internacional."}, {"c": "dou-paragraph", "t": "CAPÍTULO IV"}, {"c": "dou-paragraph", "t": "ACESSO AO SISTEMA INFORMATIZADO DO MINISTÉRIO DA AGRICULTURA E PECUÁRIA"}, {"c": "dou-paragraph", "t": "Art. 119. O cadastro e a disponibilização de acesso ao sistema informatizado do Ministério da Agricultura e Pecuária para os usuários devem ser realizados pelo serviço oficial."}, {"c": "dou-paragraph", "t": "Parágrafo único. É de exclusiva responsabilidade do usuário a manutenção do sigilo sobre a senha que integra a sua identificação eletrônica, não sendo admitida, em qualquer hipótese, a alegação de uso indevido."}, {"c": "dou-paragraph", "t": "Art. 120. O cadastro dos usuários dos estabelecimentos nacionais para acesso ao sistema informatizado do Ministério da Agricultura e Pecuária deve ser solicitado pelo seu representante legal."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os procedimentos de cadastro e acesso estão estabelecidos nas diretrizes em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 121. Quando os usuários cadastrados deixarem de exercer função relacionada à solicitação dos documentos de trânsito, o representante legal deve solicitar o cancelamento de acesso dos usuários ao sistema informatizado do Ministério da Agricultura e Pecuária para o Serviço de Inspeção de Produtos de Origem Animal da área de abrangência do estabelecimento nacional."}, {"c": "dou-paragraph", "t": "Art. 122. As orientações para utilização dos sistemas informatizados de que trata esta portaria devem ser disponibilizadas em sítio eletrônico do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "CAPÍTULO V"}, {"c": "dou-paragraph", "t": "AÇÕES FISCAIS"}, {"c": "dou-paragraph", "t": "Art. 123. O descumprimento do disposto nesta portaria implicará na adoção de ações fiscais, sem prejuízo das demais sanções administrativas previstas na legislação."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Ações fiscais relativas à habilitação"}, {"c": "dou-paragraph", "t": "Art. 124. A suspensão cautelar da habilitação do estabelecimento nacional é a suspensão da produção e do trânsito de produtos para um ou mais países importadores."}, {"c": "dou-paragraph", "t": "Art. 125. A suspensão cautelar da habilitação pode ocorrer:"}, {"c": "dou-paragraph", "t": "I - por país ou mercado comum importador;"}, {"c": "dou-paragraph", "t": "II - por categoria de produtos; ou"}, {"c": "dou-paragraph", "t": "III - por produto padronizado."}, {"c": "dou-paragraph", "t": "Art. 126. A suspensão cautelar da habilitação do estabelecimento nacional pode ocorrer pelos seguintes motivos:"}, {"c": "dou-paragraph", "t": "I - perda de controle do processo produtivo pelo estabelecimento nacional, com descumprimento dos requisitos sanitários do país ou mercado comum importador;"}, {"c": "dou-paragraph", "t": "II - determinação do país ou mercado comum importador; ou"}, {"c": "dou-paragraph", "t": "III - determinação do Departamento de Inspeção de Produtos de Origem Animal devido a evento adverso ou a acordo ou protocolo bilateral."}, {"c": "dou-paragraph", "t": "Parágrafo único. Outros motivos de suspensão cautelar da habilitação podem ser estabelecidos pelo Departamento de Inspeção de Produtos de Origem Animal ou pelo país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "Art. 127. Com a suspensão cautelar da habilitação do estabelecimento nacional, fica proibida a produção de produtos e a emissão de documentos de trânsito para o país importador."}, {"c": "dou-paragraph", "t": "Parágrafo único. É permitido o envio de produtos e a emissão de documentos de trânsito ao país importador para estoques de produtos produzidos antes da suspensão cautelar de habilitação, desde que não haja restrições do serviço oficial ou das autoridades sanitárias estrangeiras."}, {"c": "dou-paragraph", "t": "Art. 128. O estabelecimento nacional deve apresentar plano de ação com medidas corretivas e preventivas, com comprovação de atendimento aos requisitos sanitários do país ou mercado comum importador, para a avaliação do encerramento da suspensão cautelar de habilitação."}, {"c": "dou-paragraph", "t": "Art. 129. Caso o país ou mercado comum importador comunique ao Ministério da Agricultura e Pecuária o encerramento da suspensão cautelar da habilitação do estabelecimento nacional, o Departamento de Inspeção de Produtos de Origem Animal deve realizar o registro no sistema informatizado do Ministério da Agricultura e Pecuária e comunicar ao estabelecimento nacional."}, {"c": "dou-paragraph", "t": "Art. 130. A exclusão da habilitação é a perda da habilitação para exportação de produtos de origem animal a um determinado país ou mercado comum."}, {"c": "dou-paragraph", "t": "§ 1º A exclusão da habilitação ocorre por solicitação voluntária do estabelecimento nacional exportador; por determinação do Ministério da Agricultura e Pecuária ou por solicitação do país ou mercado comum importador."}, {"c": "dou-paragraph", "t": "§ 2º Produtos produzidos antes da exclusão da habilitação não podem ser exportados ao país ou mercado comum."}, {"c": "dou-paragraph", "t": "§ 3º O Departamento de Inspeção de Produtos de Origem Animal deve comunicar a exclusão de habilitação às partes interessadas."}, {"c": "dou-paragraph", "t": "Art. 131. A desabilitação de produto é a perda da autorização de exportação do produto."}, {"c": "dou-paragraph", "t": "§ 1º A desabilitação de produto ocorre por descumprimento dos requisitos sanitários do país importador."}, {"c": "dou-paragraph", "t": "§ 2º A desabilitação de produtos pode ser aplicada de forma total ou restrita a lotes específicos."}, {"c": "dou-paragraph", "t": "§ 3º É proibida a emissão de documentos de trânsito para o país importador para o qual o produto foi desabilitado."}, {"c": "dou-paragraph", "t": "§ 4º O produto desabilitado em estoque no estabelecimento nacional deve ter sua destinação avaliada pelo serviço oficial."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Ações fiscais relativas ao trânsito e à certificação sanitária"}, {"c": "dou-paragraph", "t": "Art. 132. Quando houver evidência ou suspeita da perda de controle do processo de certificação sanitária e de emissão da Declaração de Produtos de Origem Animal, o serviço oficial pode adotar as seguintes ações fiscais:"}, {"c": "dou-paragraph", "t": "I - suspensão e exclusão do acesso de usuários aos respectivos sistemas informatizados;"}, {"c": "dou-paragraph", "t": "II - suspensão cautelar da emissão dos documentos de trânsito;"}, {"c": "dou-paragraph", "t": "III - apreensão cautelar de produtos destinados à exportação; e"}, {"c": "dou-paragraph", "t": "IV - determinação do retorno dos produtos expedidos para reinspeção oficial."}, {"c": "dou-paragraph", "t": "§ 1º As ações fiscais devem ser adotadas de forma cautelar ou mediante processo administrativo, isoladas ou cumulativamente, sem prejuízo às demais ações cabíveis."}, {"c": "dou-paragraph", "t": "§ 2º O estabelecimento nacional terá o prazo de vinte dias úteis para correção das não conformidades."}, {"c": "dou-paragraph", "t": "§ 3º Após o prazo de que trata o § 2º, a suspensão cautelar da certificação deve ser convertida em suspensão cautelar da habilitação."}, {"c": "dou-paragraph", "t": "§ 4º Sempre que necessário, deverá ser determinada a revisão dos programas de autocontrole do estabelecimento nacional."}, {"c": "dou-paragraph", "t": "Art. 133. A suspensão de certificação sanitária e de emissão da Declaração de Produtos de Origem Animal deve ser registrada pelo serviço oficial no sistema informatizado do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "CAPÍTULO VI"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES FINAIS"}, {"c": "dou-paragraph", "t": "Art. 134. Os casos omissos ou as dúvidas que forem suscitadas na execução desta portaria devem ser resolvidos pelo Departamento de Inspeção de Produtos de Origem Animal."}, {"c": "dou-paragraph", "t": "Art. 135. Fica revogada a Portaria SDA/MAPA nº 431, de 19 de outubro de 2021."}, {"c": "dou-paragraph", "t": "Art. 136. Esta portaria entra em vigor em trinta dias da data de sua publicação."}, {"c": "dou-paragraph", "t": "NOME COMPLETO"}, {"c": "dou-paragraph", "t": "CARGO"}, {"c": "nota", "t": "Republicada por ter saído, no DOU nº 174-D, de 15-9-2026, Seção 1 - Extra, pág. 1, com incorreção no original."}]});